ALTER TABLE quiz_questions ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE quizzes ALTER COLUMN id SET DEFAULT gen_random_uuid();

BEGIN;
DELETE FROM quiz_questions WHERE quiz_id IN (SELECT id FROM quizzes WHERE course_id='7618517c-88a8-4949-8cbf-bcc091271abc' AND quiz_sequence=1);
DELETE FROM quizzes WHERE course_id='7618517c-88a8-4949-8cbf-bcc091271abc' AND quiz_sequence=1;
VALUES (gen_random_uuid(), '7618517c-88a8-4949-8cbf-bcc091271abc', 'Module 1 Assessment', 'Twenty questions on the fundamentals of Candle Making & Scent Blending.', 70, 30, 'module', 'beginner', 1);
COMMIT;

SELECT COUNT(*) AS questions_loaded FROM quiz_questions
WHERE quiz_id = (SELECT id FROM quizzes WHERE course_id='7618517c-88a8-4949-8cbf-bcc091271abc' AND quiz_sequence=1);
-- expect 20
